import{_ as e,o as a,c as o,aa as n}from"./chunks/framework.BAs_AphD.js";const r="/buildary-help-preview/academy/img/dashboard/02.webp",d="/buildary-help-preview/media/cs/tickets/kalendar.png",y=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{"title":"Dashboard","wiki":"cs:tickets:dashboard"},"headers":[],"relativePath":"tickets/dashboard.md","filePath":"tickets/dashboard.md","lastUpdated":1794209661000}'),l={name:"tickets/dashboard.md"};function s(k,t,i,h,p,c){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><p><strong>Dashboard</strong> je nástěnka úkolů stavby: v grafech ukazuje, kolik úkolů je v jakém stavu a kategorii, vypisuje úkoly s termínem tento týden a úkoly po termínu. Zároveň slouží jako rozcestník na seznam úkolů, výkresy, mapu a kalendář.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/dashboard">Zobrazit přehled úkolů v grafech</a> v Akademii.</p><p>Dashboard otevřete v levém panelu v části <strong>Management úkolů</strong>.</p><figure class="shot" style="--w:760px;"><img src="'+r+'" alt="Dashboard s horním řádkem tlačítek, grafy Moje úkoly, Všechny úkoly a Kategorie a seznamy Nadcházející úkoly tento týden a Úkoly po termínu" loading="lazy"></figure><h2 id="horni-radek" tabindex="-1">Horní řádek <a class="header-anchor" href="#horni-radek" aria-label="Permalink to &quot;Horní řádek&quot;">​</a></h2><p>Vlevo je dnešní datum, vedle něj tlačítka:</p><table tabindex="0"><thead><tr><th>Tlačítko</th><th>Co ukazuje</th><th>Kam vede</th></tr></thead><tbody><tr><td><strong>Seznam úkolů</strong></td><td>počty úkolů podle stavu</td><td><a href="/buildary-help-preview/tickets/task_grid">Seznam úkolů a filtry</a></td></tr><tr><td><strong>Výkresy</strong></td><td>počet úkolů umístěných na výkresech</td><td>záložka Výkresy na stránce <a href="/buildary-help-preview/tickets/task_drawings">Výkresy a mapa</a></td></tr><tr><td><strong>Mapa</strong></td><td>počet úkolů umístěných v mapě</td><td>záložka Mapa na stránce <a href="/buildary-help-preview/tickets/task_drawings">Výkresy a mapa</a></td></tr><tr><td><strong>Otevřít kalendář</strong></td><td>–</td><td>panel s kalendářem úkolů, viz <a href="#kalendar">Kalendář</a></td></tr></tbody></table><h2 id="grafy" tabindex="-1">Grafy <a class="header-anchor" href="#grafy" aria-label="Permalink to &quot;Grafy&quot;">​</a></h2><p>Prstencové grafy ukazují počty úkolů. Podle vašich oprávnění vidíte dva nebo tři grafy:</p><table tabindex="0"><thead><tr><th>Graf</th><th>Které úkoly</th><th>Členění</th></tr></thead><tbody><tr><td><strong>Moje úkoly</strong></td><td>úkoly, u kterých jste Řešitel nebo Schvalovatel</td><td>podle stavu</td></tr><tr><td><strong>Všechny úkoly</strong></td><td>všechny úkoly stavby – jen pro uživatele s kompetencí <strong>Vidět všechny úkoly</strong>, viz <a href="/buildary-help-preview/tickets/permissions">Kdo co smí v úkolech</a></td><td>podle stavu</td></tr><tr><td><strong>Kategorie</strong></td><td>stejné úkoly jako graf vlevo od něj</td><td>podle kategorie</td></tr></tbody></table><p>Úkoly ve stavu <strong>Koncept</strong> grafy nezapočítávají.</p><p>Grafy jsou klikací. Kliknutím na barevný úsek grafu otevřete Seznam úkolů vyfiltrovaný přesně na úkoly, kterých se úsek týká.</p><h2 id="ukoly-podle-terminu" tabindex="-1">Úkoly podle termínu <a class="header-anchor" href="#ukoly-podle-terminu" aria-label="Permalink to &quot;Úkoly podle termínu&quot;">​</a></h2><p>Pod grafy jsou dva seznamy neukončených úkolů. Podle vašich oprávnění v nich vidíte buď úkoly, u kterých jste Řešitel nebo Schvalovatel, nebo všechny úkoly stavby.</p><table tabindex="0"><thead><tr><th>Seznam</th><th>Které úkoly</th><th>Tlačítko</th></tr></thead><tbody><tr><td><strong>Nadcházející úkoly tento týden</strong></td><td>neukončené úkoly s plánovaným koncem ve zbývajících dnech tohoto týdne</td><td><strong>Všechny úkoly končící tento týden</strong> otevře Seznam úkolů s úkoly končícími od pondělí do neděle tohoto týdne, bez ohledu na stav</td></tr><tr><td><strong>Úkoly po termínu</strong></td><td>neukončené úkoly, kterým už plánovaný konec uplynul</td><td><strong>Všechny úkoly po termínu</strong> otevře Seznam úkolů s neukončenými úkoly po termínu</td></tr></tbody></table><p>Úkol, který se nestihl ukončit do plánovaného konce, se automaticky přesune ze seznamu tohoto týdne mezi úkoly po termínu. Kliknutím na předmět úkolu otevřete jeho detail.</p><h2 id="kalendar" tabindex="-1">Kalendář <a class="header-anchor" href="#kalendar" aria-label="Permalink to &quot;Kalendář&quot;">​</a></h2><p>Tlačítko <strong>Otevřít kalendář</strong> otevře vpravo panel <strong>Kalendář</strong> s aktuálním měsícem.</p><figure class="shot" style="--w:420px;"><img src="'+d+'" alt="Panel Kalendář s barevnými proužky úkolů ve dnech měsíce a seznamem začínajících, končících a probíhajících úkolů vybraného dne" loading="lazy"></figure><ul><li>Barevné proužky ve dnech ukazují úkoly <strong>Začínající</strong> (zeleně), <strong>Končící</strong> (červeně) a <strong>Probíhající</strong> (oranžově). Tlačítky nad kalendářem jednotlivé druhy skryjete nebo znovu zobrazíte.</li><li>Šipkami přecházíte mezi měsíci, tlačítkem <strong>Přepnout na dnešní den</strong> se vrátíte na dnešek.</li><li>Kliknutím na den zobrazíte pod kalendářem úkoly toho dne rozdělené na začínající, končící a probíhající.</li><li>Kliknutím na název úkolu otevřete jeho detail.</li></ul>',21)])])}const m=e(l,[["render",s]]);export{y as __pageData,m as default};
